window.kbPageData["views/practice/s-c6bd983baf5dd3ae"] = {"key":"practice/s-c6bd983baf5dd3ae","state":{"route":"practice/s-c6bd983baf5dd3ae"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\" open><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\" aria-current=\"page\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 地市级 申论#3":"fdbd142b0108c60966459e93","国考 2023 行政执法 申论#2":"fdbd142b0108c60966459e93","国考 2024 副省级 申论#4":"fdbd142b0108c60966459e93","国考 2024 地市级 申论#4":"90337058558938065ab64f6c","国考 2024 行政执法 申论#4":"90337058558938065ab64f6c","国考 2025 副省级 申论#4":"90337058558938065ab64f6c","国考 2025 地市级 申论#3":"b717560ed11a59693735aedd","国考 2025 行政执法 申论#4":"b717560ed11a59693735aedd"},"questions":{"国考 2023 地市级 申论#3":{"paper":"国考 2023 地市级 申论","n":3,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",2]},"国考 2023 行政执法 申论#2":{"paper":"国考 2023 行政执法 申论","n":2,"mod":"申论","src":["6d1ab3337cf152c6c10f.pdf",4],"asrc":["c433c5baa0d4806d0f4a.pdf",1]},"国考 2024 副省级 申论#4":{"paper":"国考 2024 副省级 申论","n":4,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",3]},"国考 2024 地市级 申论#4":{"paper":"国考 2024 地市级 申论","n":4,"mod":"申论","src":["a79e2681008a994c88a1.pdf",4],"asrc":["a3a840c0e3e8755b8daa.pdf",3]},"国考 2024 行政执法 申论#4":{"paper":"国考 2024 行政执法 申论","n":4,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",3]},"国考 2025 副省级 申论#4":{"paper":"国考 2025 副省级 申论","n":4,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",3]},"国考 2025 地市级 申论#3":{"paper":"国考 2025 地市级 申论","n":3,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",2]},"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3]}},"first":{"qs":{"国考 2023 地市级 申论#3":{"paper":"国考 2023 地市级 申论","n":3,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",2],"m":["d4e0e7e85f06007d"],"task":"以S市新能源办公室调研组成员的身份，根据材料3梳理整县屋顶分布式光伏开发试点中的问题，并在400字以内提出具体可行的建议。","current_affairs":{"state":"否","event":null,"year":null,"basis":"材料所述整县屋顶分布式光伏开发试点名单于2021年公布，早于2023至2026年窗口。作答可依据材料给出的试点要求和调研情况。"},"links":[{"id":"k-e7367a6531ecfefb","label":"整县屋顶分布式光伏开发试点的自愿参与、公平竞争与政府履职要求","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M1","quote":"“自愿不强制、试点不审批、到位不越位、竞争不垄断、工作不暂停”","why":"试点要求为判断暂停项目和独家包揽县域屋顶资源是否妥当提供依据。","origin":"逐题标记"},{"id":"k-327f63b6606c579e","label":"整县光伏独家开发的竞争与农户收益风险","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"而在S市已实行“一企包一县”的区域，收益则普遍降低至40元左右。","why":"材料中的区域对比支持识别独家开发的农户收益风险，并为开放合格企业参与竞争提供理由。","origin":"逐题标记"},{"id":"k-cfce047550979796","label":"户用光伏市场的企业资质、产品质量与合同履约监管","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"审核企业资质，确保企业合规运营及产品质量合格；建立合同范本文库","why":"企业资质、产品质量和合同履约监管分别回应材料中的经营失范、设备故障和农户合同权益受损。","origin":"逐题标记"},{"id":"k-db6e1fa93c55e94a","label":"整县光伏开发的产权协调、业务对接与户用备案服务","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"屋顶的产权开发协调需要企业单独去跑。今年开始安装户用，但到底是一户一户单\n独备案，还是打包备案，目前这一块还没明确。","why":"企业独自协调屋顶产权和户用备案口径不明确，构成设置政府对接人和细化备案规定的依据。","origin":"逐题标记"},{"id":"s-75a1eb1e46268fd8","label":"从调研材料的多方陈述中提取并归类问题","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"问题梳理全面、准确、有条理","why":"需综合农户、企业、政府和专家的陈述，把具体情形归纳为开发模式、市场秩序和政策服务问题。","origin":"逐题标记"},{"id":"s-c6bd983baf5dd3ae","label":"针对已归类的问题拟定有明确执行措施的对策","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"所提建议具体明确，切实可行","why":"需逐类回应问题，将改进方向落实为开放竞争、加强监管和完善政务服务等具体措施。","origin":"逐题标记"}],"stem":"假如你是S市新能源办公室调研组成员，请根据“给定资料3”，梳理S市在推进整县屋顶分布式光伏开发试点过程\n中存在的问题，并提出解决问题的建议。（20分）\n要求：\n（1）问题梳理全面、准确、有条理；\n（2）所提建议具体明确，切实可行；\n（3）不超过400字。","options":[],"answer":"","analysis":"问题：\n  1.开发模式不合理。推行“一企包一县”模式，大企业垄断市场，且不熟悉分布式光伏，未能发挥优势，农户收益\n降低。\n  2.市场秩序混乱。行业准入门槛低，企业鱼龙混杂；部分企业合同欺诈，乱收费，设备易损坏，安装后企业失\n联，无人维修。\n  3.政策服务不完善。县政府未设置专门的业务对接人，屋顶产权开发协调服务缺位；户用设备备案规定不明确。\n  建议：\n  1.坚持市场主导。向所有符合条件的企业开放，鼓励有经验及优势的中小企业参与竞争，按照市场化原则自主确\n定开发主体，营造公平自由的竞争环境，保障群众收益。\n  2.维护市场秩序。设置行业门槛，审核企业资质，确保企业合规运营及产品质量合格；建立合同范本文库，畅通\n监督反馈渠道，制定保证金制度，设置行业黑名单。\n   3.完善政策服务。政府设置专项业务对接人，联合企业共同推进产权开发协调，深入调研了解企业需求，及时提\n供优质服务；结合实际，制定明确备案规定，填补政策空白。\n   参考答案说明：本参考答案分为“问题”和“建议”两个部分。其中，“问题”部分，从“开发模式不合理”“市场秩序混\n乱”“政策服务不完善”三个方面展开；“建议”部分，从“坚持市场导向”“维护市场秩序”“完善政策服务”三个方面展开。各\n条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","经济"],"nature":"综合题","current":false},"国考 2023 行政执法 申论#2":{"paper":"国考 2023 行政执法 申论","n":2,"mod":"申论","src":["6d1ab3337cf152c6c10f.pdf",4],"asrc":["c433c5baa0d4806d0f4a.pdf",1],"m":["13e4f87e5435a6c6"],"task":"以H市市场监管部门参会代表的身份，根据材料2概述无人经济的发展现状，并针对监管问题拟写一份不超过450字的座谈会发言提纲。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料中的业态案例和监管问题，无需掌握窗口内实际发生的事件或政策部署。"},"links":[{"id":"k-bb11bb42a5197018","label":"无人经济新业态满足安全、便利和多元消费需求","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"满足了消费者\n对安全、便利和多元生活的需求","why":"材料以无人配送、便利店等业态说明其消费价值，为交代发言背景提供依据。","origin":"逐题标记"},{"id":"k-e2bc3194c80ffd14","label":"无人经营场所的设备养护与现场应急","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"建议店内设置紧急呼叫开关，\n并建立应急机制","why":"设备养护用于防范故障，紧急呼叫和应急处置用于应对消费者被困等情况。","origin":"逐题标记"},{"id":"k-bd815f986fd80b99","label":"无人业态的产品服务抽检与投诉限时反馈","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"并畅通消费者投诉渠道，建立限时反馈机制","why":"材料中的食品质量问题和投诉回应迟缓，分别对应抽检和限时反馈。","origin":"逐题标记"},{"id":"k-392aceae4d40e508","label":"无人食品经营许可须明确经营范围和发证依据","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"经营范围不明，相关许可证发放依据不清","why":"无人咖啡屋缺少可循的审批标准，说明需要通过专家和行业意见完善审批依据。","origin":"逐题标记"},{"id":"k-3f74f607fcb6f0e7","label":"无人宾馆适用旅馆业治安和公共场所卫生规则","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"M1","quote":"应依照治安管理处罚法、旅馆业治安管理办法、公共场所卫生管理条例等进行管理","why":"无人宾馆仍属旅馆业，适用相关行业规则，并由有关职能部门履行监管职责。","origin":"逐题标记"},{"id":"s-c6bd983baf5dd3ae","label":"归并材料中的监管问题并逐类拟定对策","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"主体部分从“确保硬件安全”“加强质量监管”“完善审批体系”“落实主体职责”四个方面给出了具体的对策。","why":"把不同业态案例中的问题按监管环节归并，再为每类问题提出相应措施。","origin":"逐题标记","originalId":"s-503008c490816550"}],"stem":"H市计划召开关于促进本市“无人经济”新业态健康发展的座谈会，假如你是市场监管部门的参会代表，将在座谈会\n上发言，请根据“给定资料2”，写一份发言提纲。（20分）\n要求：\n（1）紧扣资料，内容具体；\n（2）层次分明，有逻辑性；\n（3）不超过450字。","options":[],"answer":"","analysis":"关于促进H市“无人经济”新业态健康发展的发言提纲\n   背景：我市“无人经济”业态发展良好，极大地满足了消费者的各种需求，但同时，监管部门在履职过程中也发现\n了一些问题。为此，我部门计划做出以下努力：\n   举措：一、确保硬件安全。协助企业制定设备日常养护制度，并严格监督落实；建议店内设置紧急呼叫开关，\n并建立应急机制，第一时间解决消费者被困等紧急情况。二、加强质量监管。对相关产品、服务等进行高密度、不\n定期抽检，对违法企业严罚，并畅通消费者投诉渠道，建立限时反馈机制，倒逼商家及时改进、解决问题。三、完\n善审批体系。邀请专家学者、行业代表等参与讨论，广泛征求意见，明确新业态主体经营范围和相关许可证的发放\n依据，为今后工作提供权威依据。四、落实主体职责。参照新业态对应的传统行业，明确监管主体与适用的法律、\n管理制度，并由相关职能部门联合履行监管职责，消除监管盲区，防止野蛮生长。\n   结语：以上发言是抛砖引玉，希望各位参会代表踊跃发言，提出更好的意见建议。\n   参考答案说明：（1）格式方面，本参考答案写到了“标题”“正文”两个部分。（2）正文部分，一方面从内容上来\n看，围绕“‘无人经济’新业态健康发展”这一主题，本参考答案的开头先写到了“‘无人经济’发展的现状和存在的问题\n等”；主体部分从“确保硬件安全”“加强质量监管”“完善审批体系”“落实主体职责”四个方面给出了具体的对策。另一方\n面，形式上，本参考答案做到了分段、分条撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","法律"],"nature":"综合题","current":false},"国考 2024 副省级 申论#4":{"paper":"国考 2024 副省级 申论","n":4,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",3],"m":["6644520b217e1626"],"task":"以督导调研组成员身份，依据材料4草拟一份不超过500字的汇报正文，概括C市高标准农田建设成效和存在的问题，并逐项提出改进建议。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的地方调研情况、项目要求和整改依据均由材料给出，题目未要求识别窗口内发生的特定事件或政策部署。"},"links":[{"id":"k-3e95b77eeabd0099","label":"高标准农田建设","catalog_id":"18b15dd81bc52dab","type":"原理与机制","role":"直接考查","field":"M1","quote":"巩固和提高粮食生产能力、保障国家粮食安全的关键举措","why":"材料明确了高标准农田建设的目标，汇报需结合灌溉条件和亩均效益的改善说明建设成效。","origin":"逐题标记"},{"id":"k-7abd42f3d3e3ebc0","label":"农田连片整合促进土地流转与规模经营","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"统一整合分散土地，进行土地流转，推动规模化种植","why":"材料以长平县为例，说明整合分散地块后可通过土地流转促进规模经营，并增加农户租金和务工收入。","origin":"逐题标记"},{"id":"k-be0407994ebcc946","label":"农田基础设施改善为因地制宜发展特色农业创造条件","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"各乡因地制宜推进产业结构调整","why":"材料以稻油、稻鱼等特色产业的发展说明基础设施改善后如何优化产业结构、提高农业综合效益。","origin":"逐题标记"},{"id":"k-e6fbd439ca279965","label":"高标准农田原则上全部用于粮食生产","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"M1","quote":"高标准农田原则上全部用于\n粮食生产","why":"粮食生产用途要求为判断现有果园划入规划地块时的图实不符问题提供依据。","origin":"逐题标记"},{"id":"k-fbe56f334fecd67b","label":"高标准农田建设项目须按批复设计实施和验收，变更须事先获批","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"审核验收工作需严格执行批复的初步设计，未经批复同意的调整不予通过。","why":"项目应先报批再调整，验收应核对批复设计及获批变更，据此判断仅核对完成数量的做法存在问题。","origin":"逐题标记"},{"id":"k-abf275cf7d287f0a","label":"高标准农田田间道的连接对象与通行用途","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"M1","quote":"田间道是指连接田块与村庄、田块之间","why":"田间道用于农田耕作及农用物资、农产品运输，连接田块的要求是判断福树村所修道路是否合规的依据。","origin":"逐题标记"},{"id":"k-1d9d287163ec3883","label":"C市改造后高标准农田须由施工单位统一增施有机肥","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"M1","quote":"有机肥应通过施工单位统一实施入田，严禁“以发代施”","why":"C市的施肥要求用于判断按人口分发有机肥的做法，并明确整改应落实到统一施肥入田。","origin":"逐题标记"},{"id":"s-171ebed39b4fe1cf","label":"从调研材料中归纳建设成效与实施问题","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"从成果、问题、建议三个方面展开","why":"将不同地区的走访事例提炼为可并列呈现的成效和问题要点，为汇报正文组织材料。","origin":"逐题标记","originalId":"s-4c269be6e630b720"},{"id":"s-c6bd983baf5dd3ae","label":"按问题成因和管理要求逐项拟定整改措施","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"问题与建议一一对应。","why":"根据每项问题的成因或违反的要求，确定相应的整改环节和做法。","origin":"逐题标记","originalId":"s-87f603578bf566aa"}],"stem":"“给定材料4”反映了C市高标准农田建设过程中的一些情况，调研结束后，督导调研组拟向局领导汇报调研情况，\n并提出改进建议。假如你是调研组成员，请草拟汇报的主要内容。（20分）\n要求：\n（1）紧扣材料，内容全面；\n（2）简明扼要，条理清晰；\n（3）不超过500字。","options":[],"answer":"","analysis":"一、成果：1.农田得以改良。修复重建水利和农田配套设施，将旱田改造成水浇田，让种田更轻松，土地产值和\n亩均效益提升，农户种粮积极性提高。2.收入得以提升。统一整合分散土地，进行土地流转，推动规模化种植，提升\n土地租金收入，还通过务工增加工资收入。3.产业结构得以优化。农田基础设施条件显著改善，特色优势产业稳步发\n展，农业综合效益明显提升。\n  二、问题：1.实际和规划不符。上级政府不了解基层情况，直接划分区域、分派任务。2.审核验收不严格。随意\n调整和变更地块，仅要求完成数与规划数一致。3.配套设施不合规。占用高标准农田建设资金，修建非“田间道”。4.\n田间管理不到位。有机肥“以发代施”，导致村民挪用专用有机肥。\n  三、建议：1.确保规划符合实际。做规划前深入开展调研，形成意见后由基层确认，确保符合基层情况。2.严格\n把关审核验收。审核验收工作需严格执行批复的初步设计，未经批复同意的调整不予通过。3.严肃落实设施建设。严\n格审核配套设施规划图，做到专款专用，确保道路等设施建设合乎规定。4.切实加强田间管理。有机肥严格通过施工\n单位统一实施入田，杜绝将肥料发放给农户的现象。\n  参考答案说明：（1）“草拟汇报”提示本题为公文题，但题干要求写“主要内容”，所以不必考虑格式，只写正文的\n主体部分即可。（2）本参考答案宏观上从成果、问题、建议三个方面展开。其中，成果围绕“农田得以改良”“收入得\n以提升”“产业结构得以优化”三个方面进行了分条撰写；问题围绕“实际和规划不符”“审核验收不严格”“配套设施不合\n规”“田间管理不到位”四个方面进行了分条撰写；建议围绕“确保规划符合实际”“严格把关审核验收”“严肃落实设施建\n设”“切实加强田间管理”四个方面进行了分条撰写。问题与建议一一对应。各条要点之间在内容上相互并列，没有交\n叉。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","经济"],"nature":"综合题","current":false}},"materialFiles":{"d4e0e7e85f06007d":"b9ea366b4fb4a8d598cd42d7","13e4f87e5435a6c6":"6eafc7dfeca8e3158383fa45","6644520b217e1626":"48526faa975a5120c75076ed"},"terms":{"k-e7367a6531ecfefb":{"id":"k-e7367a6531ecfefb","mode":"k","type":"制度与规则","title":"整县屋顶分布式光伏开发试点工作要求","qs":[],"count":1},"k-327f63b6606c579e":{"id":"k-327f63b6606c579e","mode":"k","type":"观点与论证","title":"“一企包一县”的竞争与收益风险","qs":[],"count":1},"k-cfce047550979796":{"id":"k-cfce047550979796","mode":"k","type":"观点与论证","title":"户用光伏市场监管建议","qs":[],"count":1},"k-db6e1fa93c55e94a":{"id":"k-db6e1fa93c55e94a","mode":"k","type":"观点与论证","title":"整县光伏开发的对接与备案服务","qs":[],"count":1},"s-75a1eb1e46268fd8":{"id":"s-75a1eb1e46268fd8","mode":"s","type":"归纳概括","title":"归类概括材料中的问题","qs":[],"count":5},"s-c6bd983baf5dd3ae":{"id":"s-c6bd983baf5dd3ae","mode":"s","type":"提出对策","title":"根据问题成因逐项提出措施","qs":[],"count":8},"k-bb11bb42a5197018":{"id":"k-bb11bb42a5197018","mode":"k","type":"观点与论证","title":"无人经济的消费需求","qs":[],"count":1},"k-e2bc3194c80ffd14":{"id":"k-e2bc3194c80ffd14","mode":"k","type":"观点与论证","title":"无人经营场所的设备养护与应急","qs":[],"count":1},"k-bd815f986fd80b99":{"id":"k-bd815f986fd80b99","mode":"k","type":"观点与论证","title":"无人业态的质量抽检与投诉反馈","qs":[],"count":1},"k-392aceae4d40e508":{"id":"k-392aceae4d40e508","mode":"k","type":"观点与论证","title":"无人食品经营许可的范围与发证依据","qs":[],"count":1},"k-3f74f607fcb6f0e7":{"id":"k-3f74f607fcb6f0e7","mode":"k","type":"观点与论证","title":"无人宾馆的旅馆业监管","qs":[],"count":1},"k-3e95b77eeabd0099":{"id":"k-3e95b77eeabd0099","mode":"k","type":"概念与词义","title":"高标准农田","qs":[],"count":4},"k-7abd42f3d3e3ebc0":{"id":"k-7abd42f3d3e3ebc0","mode":"k","type":"原理与机制","title":"农田连片整合与土地流转","qs":[],"count":1},"k-be0407994ebcc946":{"id":"k-be0407994ebcc946","mode":"k","type":"原理与机制","title":"农田基础设施改善与特色农业发展","qs":[],"count":1},"k-e6fbd439ca279965":{"id":"k-e6fbd439ca279965","mode":"k","type":"制度与规则","title":"高标准农田的粮食生产用途要求","qs":[],"count":1},"k-fbe56f334fecd67b":{"id":"k-fbe56f334fecd67b","mode":"k","type":"制度与规则","title":"高标准农田项目设计变更与验收","qs":[],"count":1},"k-abf275cf7d287f0a":{"id":"k-abf275cf7d287f0a","mode":"k","type":"概念与词义","title":"田间道","qs":[],"count":1},"k-1d9d287163ec3883":{"id":"k-1d9d287163ec3883","mode":"k","type":"制度与规则","title":"C市高标准农田有机肥施用要求","qs":[],"count":1},"s-171ebed39b4fe1cf":{"id":"s-171ebed39b4fe1cf","mode":"s","type":"应用文写作","title":"汇报与交流发言","qs":[],"count":5}},"questions":{}},"firstMaterials":[{"key":"d4e0e7e85f06007d","value":["材料3","材料3\n  “光伏电站装到一半，村里突然来人告诉我不要装了，说是后面会有其他厂商统一安装，可是我已经装好的那部\n分怎么办？总不能拆掉吧？”\n   近日，S市的一些群众陆续向市能源局反映，在安装屋顶光伏电站过程中遇到了一些麻烦事。对此，市新能源办\n公室牵头组成调研组进行了深入的实地走访调查。\n   2021年9月，国家有关部门公布了整县（市、区）屋顶分布式光伏开发试点名单，强调各试点地区要严格落\n实“自愿不强制、试点不审批、到位不越位、竞争不垄断、工作不暂停”的工作要求，不断改善新能源开发建设营商环\n境，降低屋顶分布式光伏开发建设成本，减轻投资开发企业负担，相关部门要加强监管。其中，S市有10个县被列入\n试点名单。\n   “随着分布式光伏‘整县推进’步伐不断加快，屋顶光伏行业迎来跨越式发展，吸引了大型国企民企和众多中小企业\n前来角逐。”S市C县一光伏品牌代理商陈经理告诉调研组，“一个县的屋顶资源有限，僧多粥少，竞争自然非常激\n烈。”陈经理说，为此他特意扩大了业务人员规模，准备逐村逐户进行“地毯式”开拓。但是，就在他准备大展身手之\n际，却发现当地屋顶光伏的建设进度放缓了。\n   为何更多企业参与之后，反而“拖累”了屋顶光伏“整县推进”的步伐？调研组了解到，与这一现象同时出现的，是\n不少地方正在探索“一企包一县”的开发模式。\n   “所谓‘一企包一县’，就是地方政府将整个县的屋顶资源，都打包交给一家企业去做。”分布式光伏行业资深专家\n谭先生告诉调研组，“农户屋顶资源是建一户少一户，谁掌握了这些终端资源，谁就能在未来的市场竞争中拥有话语\n权。”\n   B县的一位光伏代理商汪经理也告诉调研组，自己已经半年没有新项目了。半年前，B县政府曾发布一则通知，\n暂缓全县范围内一切光伏项目。他说：“虽然文件也明确指出支持各类市场主体参与整县分布式光伏开发，企业可根\n据自身条件和优势，通过市场竞争方式参与整县规模化开发，但最终政府还是将整县资源打包交给了一家大型国\n企。”\n   B县政府相关部门工作人员告诉调研组，在建设初期，屋顶光伏领域一度处于鱼龙混杂的状态，一些不负责任的\n企业损害农户利益。地方政府在执行“整县推进”时，确实需要优先选择有实力的企业，先把市场的良性秩序建立起\n来。\n\n  调研组了解到，在光伏发电开发实施过程中，确实出现过村民受骗的情况。D县南坞村的村民老宋就向调研组讲\n述了自己被骗的经历。“前年夏天，有人来我家说可以建屋顶光伏，通过阳光发电，不仅家里以后不用交电费了，多\n余的电还可以卖钱。”老宋对调研组说，一开始，对方说自家不用花一分钱，只用提供自家屋顶就行，结果等到要安\n装时才发现，自己要垫付一部分费用，而且安装过程中还会收取很多杂七杂八的费用。如果拒绝安装，就需要交一\n部分违约金，最终他只好选择继续安装。“问题是，东西才装了不到一年就坏了，再找对方维修时，人都找不到了，\n白白亏了不少钱。”正是市场中有人“浑水摸鱼”，地方政府才不得不格外谨慎，在选择“整县推进”的合作伙伴时，更倾\n向于大型企业。\n  调研组在调查中还发现，在S市其他没有实行“一企包一县”的区域，当地农户在自家屋顶安装一个光伏电站，每\n块太阳能光伏板的大致收益是一年50元左右，而在S市已实行“一企包一县”的区域，收益则普遍降低至40元左右。\n  “一般一个农户家的屋顶光伏电站会用到60多块板子，如果实行‘一企包一县’，一年下来老百姓就会减少不少收\n入。”谭先生告诉调研组，由于光伏电站收益周期较长，对农户而言，多年累积下来，就会损失一笔不小的收入。因\n此农户会质疑，别家给的租金多，有什么理由不让他们装别家的？\n  那么，为什么会存在差价？谭先生透露说：“这可能是因为目前一些‘整县包干’的大型企业，对市场有些‘水土不\n服’。要知道，大型企业一般都是主攻集中式光伏的，对分布式光伏市场并不熟悉，其竞争优势得不到体现。因此，\n有些企业也考虑过把这项工作转包给在地方上有经验的中小公司去做。可一旦转包，在部分地区就可能存在政策、\n流程、质量等诸多不确定性风险。”\n  E县的一名光伏代理商吴经理对调研组说：“去年我们公司主要做的是三县党政机关和学校的屋顶，不过县政府\n并没有专门对接这项业务的人，屋顶的产权开发协调需要企业单独去跑。今年开始安装户用，但到底是一户一户单\n独备案，还是打包备案，目前这一块还没明确。”\n  “如今市场环境变了，原有格局被打破，新的模式尚未成熟，这个过程中，必然会暴露出各种各样的问题。”谭先\n生认为，“在这个时候能够及时发现问题、暴露矛盾也不是坏事。如果能积极探索出一种政府有为、企业有利、百姓\n受益的解决路径，就真正达到了试点的目的。”",["ac29447768aa30db2247.pdf",2]],"label":"国考 2023 地市级 申论|材料3"}],"node":{"id":"s-c6bd983baf5dd3ae","mode":"s","title":"根据问题成因逐项提出措施","type":"提出对策","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["针对已归类的问题拟定有明确执行措施的对策","归并材料中的监管问题并逐类拟定对策","按问题成因和管理要求逐项拟定整改措施","根据问题成因与材料经验拟定对应对策","按问题成因逐项拟定可执行对策","根据问题成因和实施条件拟定对应对策","依据问题及成因提出对应的可执行对策","针对检查发现的问题逐项拟定整改措施"],"qs":["国考 2023 地市级 申论#3","国考 2023 行政执法 申论#2","国考 2024 副省级 申论#4","国考 2024 地市级 申论#4","国考 2024 行政执法 申论#4","国考 2025 副省级 申论#4","国考 2025 地市级 申论#3","国考 2025 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"根据问题成因逐项提出措施","ids":["国考 2023 地市级 申论#3","国考 2023 行政执法 申论#2","国考 2024 副省级 申论#4","国考 2024 地市级 申论#4","国考 2024 行政执法 申论#4","国考 2025 副省级 申论#4","国考 2025 地市级 申论#3","国考 2025 行政执法 申论#4"],"units":[["国考 2023 地市级 申论#3"],["国考 2023 行政执法 申论#2"],["国考 2024 副省级 申论#4"],["国考 2024 地市级 申论#4"],["国考 2024 行政执法 申论#4"],["国考 2025 副省级 申论#4"],["国考 2025 地市级 申论#3"],["国考 2025 行政执法 申论#4"]]}]}};
